def parse_prefix(s):
    """Parse '<ipv6>/<len>'; returns (addr, length) or None."""
    if not is_str(s):
        return None
    i = s.find('/')
    if i < 0 or s.find('/', i + 1) >= 0:
        return None
    ls = s[i + 1:]
    ln = len(ls)
    if ln == 0 or ln > 3:
        return None
    if ls == '0':
        length = 0
    else:
        if ls[0] not in '123456789':
            return None
        for ch in ls[1:]:
            if ch not in _DEC:
                return None
        length = int(ls)
        if length > 128:
            return None
    a = parse_ipv6(s[:i])
    if a is None:
        return None
    if a & HMASK[length]:
        return None
    return (a, length)


# truncation masks: TMASK[d] keeps the top d bits
TMASK = [0] * 129
for _d in range(129):
    TMASK[_d] = MASK128 if _d == 0 else (MASK128 ^ ((1 << (128 - _d)) - 1))
TMASK[0] = 0
# host bit masks: HMASK[d] covers the low 128-d bits
HMASK = [MASK128 ^ TMASK[_d] for _d in range(129)]


def trunc(a, d):
    return a & TMASK[d]


def align_up(x, k):
    r = x % k
    return x + (k - r) if r else x


def align8(x):
    return (x + 7) >> 3 << 3


def align64(x):
    return (x + 63) >> 6 << 6


